package io.github.adkimsm.up366.hook;

import java.security.SecureRandom;
import java.util.Locale;

/**
 * Correlation identifiers shared across the module process and the hooked target process.
 *
 * <p>A {@code traceId} identifies one parse or query flow and is generated by the side that starts
 * the flow. A {@code requestId} identifies one Provider, broadcast or bridge operation and is
 * generated by the side that initiates the IPC. Both are passed through IPC arguments and written
 * back verbatim by the receiver so the two process logs can be joined.
 */
final class Trace {
    static final String ORPHAN = "orphan";

    private static final SecureRandom RANDOM = new SecureRandom();

    private Trace() {}

    static String newTraceId() {
        return randomId("t");
    }

    static String newRequestId() {
        return randomId("r");
    }

    static String hash(String value) {
        return LogSink.hash(value);
    }

    static String require(String value) {
        return value == null || value.length() == 0 ? ORPHAN : value;
    }

    private static String randomId(String prefix) {
        byte[] bytes = new byte[6];
        RANDOM.nextBytes(bytes);
        StringBuilder builder = new StringBuilder(prefix).append('-');
        for (byte value : bytes) builder.append(String.format(Locale.US, "%02x", value));
        return builder.toString();
    }
}
